INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s0-0', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-0', 0, '两平行平面与之间的距离为（）.', '两平行平面 $Ax + By + Cz = D_{1}$ 与 $Ax + By + Cz = D_{2}$ 之间的距离为（）.', '["$\\\\left||D_{2}\\\\right| - \\\\left|D_{1}\\\\right|\\\\left|\\\\right|$","$\\\\left|D_{2} - D_{1}\\\\right|$","$\\\\frac{\\\\left|\\\\left|D_{2}\\\\right| - \\\\left|D_{1}\\\\right|\\\\right|}{\\\\sqrt{A^{2} + B^{2} + C^{2}}}$","$\\\\frac{\\\\left|D_{2} - D_{1}\\\\right|}{\\\\sqrt{A^{2} + B^{2} + C^{2}}}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
