INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s0-2', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-0', 0, '设是连续函数，交换二次积分的积', '设 $f(x,y)$ 是连续函数，交换二次积分 $\\int_{0}^{1}\\mathrm{d}y\\int_{y}^{\\sqrt{y}}x\\mathrm{d}x$ 的积分次序后的结果为（）.', '["$\\\\int_{0}^{1}\\\\mathrm{d}x\\\\int_{y}^{\\\\sqrt{y}}x\\\\mathrm{d}y$","$\\\\int_{0}^{1}\\\\mathrm{d}y\\\\int_{x}^{\\\\sqrt{x}}y\\\\mathrm{d}x$","$\\\\int_{0}^{1}\\\\mathrm{d}x\\\\int_{x^{2}}^{x}x\\\\mathrm{d}y$","$\\\\int_{0}^{1}\\\\mathrm{d}x\\\\int_{x}^{x^{2}}x\\\\mathrm{d}y$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s0-3', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-0', 0, '下列结论一定正确的是（）.', '下列结论一定正确的是（）.', '["利用积分曲线的参数方程将对弧长的曲线积分转换为定积分计算时, 积分下限一定小于上限.","利用积分曲线的参数方程将对坐标的曲线积分转换为定积分计算时, 积分下限一定小于上限.","设曲面 $\\\\Sigma: z = 0, (x, y) \\\\in D$ （闭区域），则 $\\\\iint_{\\\\Sigma} f(x, y, z) dx dy = \\\\iint_{D} f(x, y, 0) dx dy.$","设曲面 $\\\\Sigma: z = 0, (x, y) \\\\in D$ （闭区域），则 $\\\\iint_{\\\\Sigma} f(x, y, z) dx dy = -\\\\iint_{D} f(x, y, 0) dx dy.$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s0-4', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-0', 0, '设，且级数与均收敛，则级数（）', '设 $a_{n} \\leq c_{n} \\leq b_{n}(n=1,2,\\cdots)$ ，且级数 $\\sum_{n=1}^{\\infty} a_{n}$ 与 $\\sum_{n=1}^{\\infty} b_{n}$ 均收敛，则级数 $\\sum_{n=1}^{\\infty} c_{n}$ （）.', '["必收敛","必发散","未必收敛，但 $\\\\lim_{n\\\\to\\\\infty}c_n=0$","$\\\\lim_{n\\\\to\\\\infty}c_n$ 存在但未必等于0"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
