INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s1-3', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-1', 2, '设L为椭圆，其周长为a，则\\_', '设 L 为椭圆 $\\frac{x^{2}}{5} + \\frac{y^{2}}{4} = 1$ ，其周长为 a，则 $\\oint_{L} (2xy + 4x^{2} + 5y^{2}) ds =$ \\_\\_\\_\\_ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
