INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s2-0', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-2', 3, '已知曲线上点处的切线与平面平行', '已知曲线 $\\Gamma: \\begin{cases} x = 1 + t \\\\ y = t \\\\ z = 1 + t^2 \\end{cases}$ 上点 $P$ 处的切线与平面 $\\pi: x + y - z = 0$ 平行，求点 $P$ 的坐标以及曲线在该点处的切线方程.', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s2-1', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-2', 3, '求函数在区域上的最大值和最小值', '求函数 $f(x, y) = x^{2} + 2y^{2} - x^{2}y^{2}$ 在区域 $D = \\{(x, y) | x^{2} + y^{2} \\leq 4, y \\geq 0\\}$ 上的最大值和最小值.', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s2-2', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-2', 3, '计算二重积分.', '计算二重积分 $\\iint_{x^2 + y^2 \\leq a^2} (x^2 - 2\\sin x + 3y + 4) d\\sigma$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s2-3', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-2', 3, '计算曲线积分，其中为由到经过圆', '计算曲线积分 $I = \\int_{\\widehat{AO}} (e^{x} \\sin y - 3y) \\, dx + (e^{x} \\cos y - 3) \\, dy$ ，其中 $\\widehat{AO}$ 为由 $A(a,0)$ 到 $O(0,0)$ 经过圆 $x^{2} + y^{2} = ax$ 上半部分的路线 $(a>0)$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2024-s2-4', 'exam-calculus-2-2024', 'exam-calculus-2-2024-sec-2', 3, '将展开成x-1的幂级数，并求.', '将 $f(x)=\\frac{x-1}{4-x}$ 展开成x-1的幂级数，并求 $f^{(n)}(1)$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2024长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
